  "level4Didactics": [
    {
      "focus": "Een eenvoudige mededeling heeft hier een topic, een beschrijving en een beleefd slot.",
      "watch": "は markeert het topic en klinkt in deze rol als wa."
    },
    {
      "focus": "これ, それ en あれ veranderen de afstand; de zinsbouw blijft hetzelfde.",
      "watch": "Kies het aanwijzend woord op basis van dit, dat bij jou of dat daar."
    },
    {
      "focus": "Het blok vóór は is het topic. Alles erna vertelt iets over dat topic.",
      "watch": "Zoek eerst は; dan zie je direct waar de zin over gaat."
    },
    {
      "focus": "X の Y betekent: Y van X. の verbindt de bezitter met wat erbij hoort.",
      "watch": "Lees na の eerst Y en voeg daarna “van X” toe."
    },
    {
      "focus": "Een bekende mededeling wordt een ja/nee-vraag door か achteraan toe te voegen.",
      "watch": "De rest van de zin verandert niet."
    },
    {
      "focus": "も betekent hier “ook” en staat op de plaats waar eerder は stond.",
      "watch": "Gebruik も alleen wanneer de tweede zin iets toevoegt aan eerdere informatie."
    },
    {
      "focus": "を markeert waarop de handeling gericht is. Het werkwoord staat achteraan.",
      "watch": "Lees: topic → object met を → handeling."
    },
    {
      "focus": "Particles tonen de rol van elk blok, ook wanneer er meerdere woorden in de zin staan.",
      "watch": "Vind は en を; controleer daarna of het werkwoord achteraan staat."
    },
    {
      "focus": "に markeert hier de bestemming: de plaats waar iemand naartoe gaat.",
      "watch": "Gebruik を voor een object van een handeling en に voor een bestemming."
    },
    {
      "focus": "Kies het patroon vanuit de betekenis: beschrijven, bezit, vraag, ook, object of bestemming.",
      "watch": "Bepaal eerst de bedoeling; kies daarna pas het juiste partikel."
    }
  ],
