  function wordTuple(id,kind){const v=byId[id];if(!v)throw new Error('Unknown vocabulary '+id);return kind==='example'?[v.japanese,v.romaji,v.meaning,v.kanjiForm,null]:[v.japanese,v.meaning,v.romaji,v.kanjiForm,null]}
